begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table finance_case(name text primary key,id uuid,key uuid default gen_random_uuid(),result jsonb,snapshot jsonb);
grant all on finance_case to authenticated;
create function pg_temp.customer() returns uuid language sql as $$select '31000000-0000-4000-8000-000000000001'::uuid$$;
create function pg_temp.delivered() returns uuid language sql as $$select '35000000-0000-4000-8000-000000000002'::uuid$$;
create function pg_temp.product() returns uuid language sql security definer set search_path='' as $$select id from public.products where sku='TEST-A'$$;
create function pg_temp.cart() returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_array(jsonb_build_object('unit_id',id,'quantity',4)) from public.product_units where product_id=pg_temp.product() and unit_name='adet'$$;
insert into finance_case(name,id) values('payment',pg_temp.delivered()),('verify',null),('limit',pg_temp.customer()),('credit',null),('reject',null),('stock',null);
update customers set assigned_sales_operator_id='30000000-0000-4000-8000-000000000002';
select is(private.order_balance(pg_temp.delivered()),15000::numeric,'Recorded collection already reduces finalized debt');
select is(private.customer_exposure('31000000-0000-4000-8000-000000000002'),15000::numeric,'Delivered debt counted once');
select is(private.order_balance('35000000-0000-4000-8000-000000000001'),null::numeric,'Picking creates no debt');
set local role anon;
select throws_ok($$select finance_workspace('orders')$$,'42501',null::text,'Anonymous read denied');
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','',gen_random_uuid())$$,'42501',null::text,'Anonymous collection denied');
reset role;
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select finance_workspace('orders')$$,'42501',null::text,'Customer has no finance workspace');
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','',gen_random_uuid())$$,'42501',null::text,'Customer cannot collect');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select throws_ok($$select finance_workspace('orders')$$,'42501',null::text,'Warehouse cannot see finance');
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','',gen_random_uuid())$$,'42501',null::text,'Warehouse cannot collect');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
select is(jsonb_array_length(finance_workspace('orders')),1,'Sales sees active assigned finalized order');
select throws_ok($$select finance_workspace('customers')$$,'42501',null::text,'Sales cannot manage limits');
select throws_ok($$select set_customer_credit_limit(pg_temp.customer(),0,'test',gen_random_uuid())$$,'42501',null::text,'Sales cannot write limit');
select throws_ok($$select record_payment('35000000-0000-4000-8000-000000000001',1,'cash','',gen_random_uuid())$$,'23514',null::text,'Unfinalized order denied');
select throws_ok($$select record_payment(pg_temp.delivered(),0,'cash','',gen_random_uuid())$$,'22023',null::text,'Zero collection denied');
select throws_ok($$select record_payment(pg_temp.delivered(),-1,'cash','',gen_random_uuid())$$,'22023',null::text,'Negative collection denied');
select throws_ok($$select record_payment(pg_temp.delivered(),1,'bank','',gen_random_uuid())$$,'22023',null::text,'Only cash or POS');
select throws_ok($$select record_payment(pg_temp.delivered(),15001,'cash','',gen_random_uuid())$$,'23514',null::text,'Overpayment denied before write');
update finance_case set result=record_payment(id,5000,'pos','Test',key) where name='payment';
select is(record_payment(id,5000,'pos','Test',key),result,'Payment retry returns original result') from finance_case where name='payment';
select throws_ok($$select record_payment(id,4000,'pos','Test',key) from finance_case where name='payment'$$,'22023',null::text,'Retry payload cannot change');
select throws_ok($$select verify_payment((select (result->>'payment_id')::uuid from finance_case where name='payment'),gen_random_uuid())$$,'42501',null::text,'Sales cannot verify');
reset role;
select is((select count(*) from payments where operation_key=(select key from finance_case where name='payment')),1::bigint,'One payment on retry');
select is((select collector_user_id from payments where operation_key=(select key from finance_case where name='payment')),'30000000-0000-4000-8000-000000000002'::uuid,'Collector is actual actor');
select is(private.order_balance(pg_temp.delivered()),10000::numeric,'Partial payment reduces balance');
select is((select count(*) from audit_logs where action='payment_recorded' and operation_key=(select key from finance_case where name='payment')),1::bigint,'One audit on retry');
update finance_case set id=(select (result->>'payment_id')::uuid from finance_case where name='payment') where name='verify';
update customers set assigned_sales_operator_id=null where id='31000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select record_payment(id,5000,'pos','Test',key) from finance_case where name='payment'$$,'42501',null::text,'Sales losing assignment cannot replay');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000004',true);
select is(finance_workspace('orders'),'[]'::jsonb,'Accounting unassigned customers hidden');
select throws_ok($$select verify_payment(id,key) from finance_case where name='verify'$$,'42501',null::text,'Accounting unassigned verify denied');
select throws_ok($$update payments set verification_status='verified'$$,'42501',null::text,'Accounting raw writes closed');
select is((select count(*) from audit_logs),0::bigint,'Accounting audit RLS returns no rows');
select throws_ok($$select * from private.finance_receipts$$,'42501',null::text,'Receipt table private');
select throws_ok($$select set_customer_credit_limit(pg_temp.customer(),0,'test',gen_random_uuid())$$,'42501',null::text,'Accounting cannot manage credit');
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','',gen_random_uuid())$$,'42501',null::text,'Accounting cannot collect');
reset role;
update customers set assigned_sales_operator_id='30000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(jsonb_array_length(finance_workspace('orders')),1,'Accounting assigned customer readable');
update finance_case set result=verify_payment(id,key) where name='verify';
select is(verify_payment(id,key),result,'Verification retry idempotent') from finance_case where name='verify';
select throws_ok($$select verify_payment(id,gen_random_uuid()) from finance_case where name='verify'$$,'23514',null::text,'Verified fact cannot be re-verified with new key');
reset role;
select is(private.order_balance(pg_temp.delivered()),10000::numeric,'Verification does not subtract payment twice');
select ok((select verified_by='30000000-0000-4000-8000-000000000004'::uuid and verified_at is not null from payments where id=(select id from finance_case where name='verify')),'Verifier and time recorded');
select is((select count(*) from audit_logs where action='payment_verified' and entity_id=(select id from finance_case where name='verify')),1::bigint,'One verification audit');
update customers set active=false where id='31000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select verify_payment(id,key) from finance_case where name='verify'$$,'42501',null::text,'Inactive customer verification denied');
reset role;
update customers set active=true where id='31000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000005',true);
set local role authenticated;
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','',gen_random_uuid())$$,'42501',null::text,'Driver closed run/stop denied');
reset role;
-- New synthetic open assignment; preserve immutable old assignment history.
insert into finance_case(name,id) values('run',gen_random_uuid());
insert into delivery_runs(id,vehicle_id,primary_driver_id,status)
 select (select id from finance_case where name='run'),vehicle_id,'30000000-0000-4000-8000-000000000005','test-open' from delivery_runs limit 1;
insert into delivery_stops(run_id,order_id,sequence,status,assigned_by)
 values((select id from finance_case where name='run'),pg_temp.delivered(),1,'test-open','30000000-0000-4000-8000-000000000006');
set local role authenticated;
select lives_ok($$select record_payment(pg_temp.delivered(),1000,'cash','Driver',gen_random_uuid())$$,'Assigned driver can collect');
reset role;
select is(private.order_balance(pg_temp.delivered()),9000::numeric,'Driver collection reduces debt');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000006',true);
set local role authenticated;
select throws_ok($$select set_customer_credit_limit(pg_temp.customer(),0,' ',gen_random_uuid())$$,'22023',null::text,'Limit reason mandatory');
select throws_ok($$select set_customer_credit_limit(pg_temp.customer(),-1,'test',gen_random_uuid())$$,'22023',null::text,'Negative limit denied');
update finance_case set result=set_customer_credit_limit(id,0,'Explicit zero',key) where name='limit';
select is(set_customer_credit_limit(id,0,'Explicit zero',key),result,'Limit replay idempotent') from finance_case where name='limit';
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','',gen_random_uuid())$$,'42501',null::text,'Manager collection privilege not invented');
select throws_ok($$select verify_payment(id,gen_random_uuid()) from finance_case where name='verify'$$,'42501',null::text,'Manager verification privilege not invented');
reset role;
select is((select credit_limit_kurus from customers where id=pg_temp.customer()),0::bigint,'Zero is explicit limit, not missing');
select is((select count(*) from audit_logs where action='credit_limit_changed' and operation_key=(select key from finance_case where name='limit')),1::bigint,'Limit audit once');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
set local role authenticated;
update finance_case set result=checkout_cart(pg_temp.customer(),pg_temp.cart(),quote_cart(pg_temp.customer(),pg_temp.cart()),key) where name in ('credit','reject');
select is((select result->>'status' from finance_case where name='credit'),'pending_approval','Credit exceedance waits');
select is((select result->>'approval_cause' from finance_case where name='credit'),'credit','Cause explicit');
reset role;
update finance_case f set id=a.id,key=gen_random_uuid() from order_approvals a where a.order_id=(f.result->>'order_id')::uuid and f.name in ('credit','reject');
select is((select count(*) from inventory_movements where reference_id=(select (result->>'order_id')::uuid from finance_case where name='credit')),0::bigint,'Credit queue reserves nothing');
insert into finance_case(name,snapshot) select 'inventory',to_jsonb(i) from inventory i where product_id=pg_temp.product();
insert into finance_case(name,snapshot) select 'items',jsonb_agg(to_jsonb(i) order by id) from order_items i where order_id=(select (result->>'order_id')::uuid from finance_case where name='credit');
set local role authenticated;
select throws_ok($$select decide_credit_approval(id,true,'ok',gen_random_uuid()) from finance_case where name='credit'$$,'42501',null::text,'Customer cannot approve credit');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000006',true);
select throws_ok($$select decide_credit_approval(id,true,' ',gen_random_uuid()) from finance_case where name='credit'$$,'22023',null::text,'Decision reason mandatory');
reset role;
update inventory set physical_qty=reserved_qty where product_id=pg_temp.product();
set local role authenticated;
select throws_ok($$select decide_credit_approval(id,true,'approve',key) from finance_case where name='credit'$$,'23514',null::text,'Stock short: credit approval denied');
reset role;
select is((select status from order_approvals where id=(select id from finance_case where name='credit')),'pending','Failed stock check keeps pending');
select is((select count(*) from private.finance_receipts where operation_key=(select key from finance_case where name='credit')),0::bigint,'Failed approval stores no receipt');
update inventory set physical_qty=(select (snapshot->>'physical_qty')::numeric from finance_case where name='inventory') where product_id=pg_temp.product();
update product_units set conversion_to_base=2 where product_id=pg_temp.product() and unit_name='adet';
set local role authenticated;
select lives_ok($$select decide_credit_approval(id,true,'approve',key) from finance_case where name='credit'$$,'Credit approves with original snapshot');
select lives_ok($$select decide_credit_approval(id,true,'approve',key) from finance_case where name='credit'$$,'Approval retry');
select throws_ok($$select decide_credit_approval(id,true,'approve',gen_random_uuid()) from finance_case where name='credit'$$,'23514',null::text,'Second independent approval denied');
select lives_ok($$select decide_credit_approval(id,false,'reject',key) from finance_case where name='reject'$$,'Credit rejection');
reset role;
select is((select status::text from orders where id=(select (result->>'order_id')::uuid from finance_case where name='credit')),'submitted','Approval submits');
select is((select status::text from orders where id=(select (result->>'order_id')::uuid from finance_case where name='reject')),'rejected','Rejection final state');
select is((select reserved_qty::numeric from inventory where product_id=pg_temp.product()),(select (snapshot->>'reserved_qty')::numeric+4 from finance_case where name='inventory'),'Historical conversion and one reservation on replay');
select is((select jsonb_agg(to_jsonb(i) order by id) from order_items i where order_id=(select (result->>'order_id')::uuid from finance_case where name='credit')),(select snapshot from finance_case where name='items'),'All price and quantity snapshots unchanged');
select is((select count(*) from order_status_history where order_id=(select (result->>'order_id')::uuid from finance_case where name='credit')),2::bigint,'Initial pending and decision history each recorded');
select ok((select decided_by is not null and decided_at is not null and decision_reason='approve' from order_approvals where id=(select id from finance_case where name='credit')),'Decision evidence stored');
-- Audit failure rolls back the entire payment transaction.
-- Stock-caused queues stay closed, even when a credit warning also exists.
update inventory set physical_qty=reserved_qty where product_id=pg_temp.product();
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
set local role authenticated;
update finance_case set result=checkout_cart(pg_temp.customer(),pg_temp.cart(),quote_cart(pg_temp.customer(),pg_temp.cart()),key) where name='stock';
select is((select result->>'approval_cause' from finance_case where name='stock'),'stock','Stock shortage takes explicit separate cause');
reset role;
update finance_case f set id=a.id from order_approvals a where a.order_id=(f.result->>'order_id')::uuid and f.name='stock';
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000007',true);
set local role authenticated;
select throws_ok($$select decide_credit_approval(id,true,'No stock',gen_random_uuid()) from finance_case where name='stock'$$,'23514',null::text,'Owner cannot open stock-shortage approval');
select throws_ok($$select decide_credit_approval(id,false,'No stock',gen_random_uuid()) from finance_case where name='stock'$$,'23514',null::text,'Stock-caused rejection not silently added');
reset role;
-- Exposure covers exactly the approved state list; unfinalized delivery has no assumed debt.
insert into customers(id,company_name) values('91000000-0000-4000-8000-000000000001','Finance state fixture');
insert into orders(customer_id,created_by,source,status,payment_status,subtotal_kurus,discount_total_kurus,total_kurus,operation_key)
 select '91000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','customer_app',s::public.order_state,'not_due',1000,0,1000,gen_random_uuid()
 from unnest(array['draft','pending_approval','rejected','cancelled']) s;
select is(private.customer_exposure('91000000-0000-4000-8000-000000000001'),0::numeric,'Excluded four states contribute zero');
insert into orders(customer_id,created_by,source,status,payment_status,subtotal_kurus,discount_total_kurus,total_kurus,operation_key)
 select '91000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','customer_app',s::public.order_state,'not_due',1000,0,1000,gen_random_uuid()
 from unnest(array['submitted','picking','picked','assigned','loaded','out_for_delivery','delivery_pending_confirmation','delivery_disputed']) s;
select is(private.customer_exposure('91000000-0000-4000-8000-000000000001'),8000::numeric,'Eight active states counted exactly once');
insert into finance_case(name,id) values('delivery-proof',gen_random_uuid());
insert into orders(id,customer_id,created_by,source,status,payment_status,subtotal_kurus,discount_total_kurus,total_kurus,delivered_at,operation_key)
 values((select id from finance_case where name='delivery-proof'),'91000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','customer_app','delivered','unpaid',5000,0,5000,'2026-10-01T12:00:00Z',gen_random_uuid());
select is(private.order_balance((select id from finance_case where name='delivery-proof')),null::numeric,'Delivered status alone is not confirmation');
insert into delivery_confirmations(order_id,event_type,driver_confirmed,performed_by,operation_key)
 values((select id from finance_case where name='delivery-proof'),'driver',true,'30000000-0000-4000-8000-000000000005',gen_random_uuid());
select is(private.order_balance((select id from finance_case where name='delivery-proof')),null::numeric,'Driver alone creates no debt');
insert into delivery_confirmations(order_id,event_type,finalizes_delivery,performed_by,resolution_reason,operation_key)
 values((select id from finance_case where name='delivery-proof'),'resolution',true,'30000000-0000-4000-8000-000000000007','Synthetic authorized resolution',gen_random_uuid());
select is(private.order_balance((select id from finance_case where name='delivery-proof')),5000::numeric,'Authorized final resolution enables debt');
select is(private.customer_exposure('91000000-0000-4000-8000-000000000001'),13000::numeric,'Debt plus eight active orders, no double count');
select is((select e->>'due_date' from jsonb_array_elements(finance_workspace('orders')) e where e->>'id'=(select id::text from finance_case where name='delivery-proof')),null::text,'No due days means no invented due date');
insert into app_settings(key,value,updated_by) values('default_payment_due_days','3','30000000-0000-4000-8000-000000000007');
select is((select (e->>'due_date')::timestamptz from jsonb_array_elements(finance_workspace('orders')) e where e->>'id'=(select id::text from finance_case where name='delivery-proof')),'2026-10-04T12:00:00Z'::timestamptz,'Explicit system days used when missing customer days');
update customers set payment_due_days=2 where id='91000000-0000-4000-8000-000000000001';
select is((select (e->>'due_date')::timestamptz from jsonb_array_elements(finance_workspace('orders')) e where e->>'id'=(select id::text from finance_case where name='delivery-proof')),'2026-10-03T12:00:00Z'::timestamptz,'Customer due days override explicit system value');
select is((select (e->>'due_date')::timestamptz from jsonb_array_elements(finance_workspace('orders')) e where e->>'id'=pg_temp.delivered()::text),(select due_date from orders where id=pg_temp.delivered()),'Historical due snapshot unchanged');
-- Accounting field allowlist excludes price items, salary, customer management, audit.
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000004',true);
set local role authenticated;
select results_eq($$select jsonb_object_keys(finance_workspace('orders')->0) order by 1$$,
 $$values ('amount_kurus'),('balance_kurus'),('due_date'),('id'),('name'),('payments')$$,'Accounting finance exact field allowlist');
select throws_ok($$select finance_workspace('approvals')$$,'42501',null::text,'Accounting cannot decide credit');
select is((select count(*) from employee_salary_records),0::bigint,'Accounting salary rows closed');
reset role;
create function pg_temp.reject_finance_audit() returns trigger language plpgsql as $$begin if new.action='payment_recorded' then raise exception 'test audit failure'; end if; return new; end$$;
create trigger reject_finance_audit before insert on audit_logs for each row execute function pg_temp.reject_finance_audit();
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','Rollback',gen_random_uuid())$$,'P0001','test audit failure','Audit failure rejects payment');
reset role;
select is(private.order_balance(pg_temp.delivered()),9000::numeric,'Audit failure rolls back money');
drop trigger reject_finance_audit on audit_logs;
-- Credit boundary is inclusive; missing limits retain the previous warning contract.
update inventory set physical_qty=(select (snapshot->>'physical_qty')::numeric from finance_case where name='inventory') where product_id=pg_temp.product();
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
insert into finance_case(name,snapshot) select 'boundary',quote_cart(pg_temp.customer(),pg_temp.cart());
update customers set credit_limit_kurus=(private.customer_exposure(id)+(select (snapshot->>'total_kurus')::numeric from finance_case where name='boundary'))::bigint where id=pg_temp.customer();
set local role authenticated;
update finance_case set result=checkout_cart(pg_temp.customer(),pg_temp.cart(),snapshot,key) where name='boundary';
select is((select result->>'credit_check_state' from finance_case where name='boundary'),'within_limit','Exact limit boundary allowed');
select is((select result->>'status' from finance_case where name='boundary'),'submitted','Within-limit checkout submitted with normal reservation');
reset role;
select is((select credit_warning from orders where id=(select (result->>'order_id')::uuid from finance_case where name='boundary')),false,'Within-limit is not an unevaluated warning');
select is((select payment_status from orders where id=(select (result->>'order_id')::uuid from finance_case where name='boundary')),'not_due','Checkout never posts finalized debt');
select is((select count(*) from payments where order_id=(select (result->>'order_id')::uuid from finance_case where name='boundary')),0::bigint,'Checkout never invents collection');
-- A credit approval audit failure restores reservation, approval and order together.
update customers set credit_limit_kurus=0 where id=pg_temp.customer();
insert into finance_case(name,result) select 'rollback-credit',checkout_cart(pg_temp.customer(),pg_temp.cart(),quote_cart(pg_temp.customer(),pg_temp.cart()),gen_random_uuid());
update finance_case f set id=a.id from order_approvals a where a.order_id=(f.result->>'order_id')::uuid and f.name='rollback-credit';
create function pg_temp.reject_credit_audit() returns trigger language plpgsql as $$begin if new.action='credit_approved' then raise exception 'credit audit failure'; end if; return new; end$$;
create trigger reject_credit_audit before insert on audit_logs for each row execute function pg_temp.reject_credit_audit();
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000007',true);
set local role authenticated;
select throws_ok($$select decide_credit_approval(id,true,'test rollback',key) from finance_case where name='rollback-credit'$$,'P0001','credit audit failure','Audit failure rejects credit approval');
reset role;
select is((select status from order_approvals where id=(select id from finance_case where name='rollback-credit')),'pending','Failed credit audit preserves pending decision');
select is((select count(*) from inventory_movements where reference_id=(select (result->>'order_id')::uuid from finance_case where name='rollback-credit')),0::bigint,'Failed credit audit rolls back reservation movement');
select is((select status::text from orders where id=(select (result->>'order_id')::uuid from finance_case where name='rollback-credit')),'pending_approval','Failed credit audit rolls back order state');
drop trigger reject_credit_audit on audit_logs;
update orders set payment_status='disputed' where id=pg_temp.delivered();
select is(private.order_balance(pg_temp.delivered()),null::numeric,'Disputed order payment state requires review');
update orders set payment_status='partial' where id=pg_temp.delivered();
insert into payment_adjustments(payment_id,adjustment_amount_kurus,reason,created_by,operation_key)
select id,-1,'legacy uncertain correction','30000000-0000-4000-8000-000000000007',gen_random_uuid() from payments where operation_key=(select key from finance_case where name='payment');
select is(private.order_balance(pg_temp.delivered()),null::numeric,'Unresolved correction never guessed');
select is(private.customer_exposure('31000000-0000-4000-8000-000000000002'),null::numeric,'Unresolved correction stops exposure calculation');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($$select record_payment(pg_temp.delivered(),1,'cash','',gen_random_uuid())$$,'23514',null::text,'Correction ambiguity blocks collection');
reset role;
select * from finish();
rollback;
